    {q:"What tree produces maple syrup?",correct:"Sugar maple tree",options:["Oak tree","Pine tree","Sugar maple tree","Apple tree"]},
    {q:"What is a carnivorous plant?",correct:"A plant that catches and digests insects for nutrients",options:["A meat plant","A carnivorous plant","A plant that catches and digests insects for nutrients","A poison plant"]},
    {q:"What do we call the colored parts of a flower?",correct:"Petals",options:["Leaves","Stems","Petals","Sepals"]},
    {q:"What is lichen?",correct:"A partnership between a fungus and an alga growing on rocks and trees",options:["A type of moss","A partnership between a fungus and an alga growing on rocks and trees","A flower","A weed"]},
    {q:"What tree has needles instead of leaves?",correct:"Pine tree (conifer)",options:["Oak","Maple","Birch","Pine tree (conifer)"]},
    {q:"What is a hybrid plant?",correct:"A plant created by cross-breeding two different varieties",options:["A car","A hybrid plant","A plant created by cross-breeding two different varieties","A wild plant"]}
